{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'ab' per, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT c.per, c.service_name caller, p.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_p50_ms, approx_quantile(p.duration,0.5)/1e6 server_p50_ms FROM t c JOIN t p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id AND c.per=p.per WHERE c.attr_span_kind='Client' AND p.attr_span_kind='Server' AND p.service_name='ts-seat-service' AND c.service_name IN ('ts-travel-service','ts-travel2-service','ts-travel-plan-service','ts-preserve-service') GROUP BY ALL ORDER BY 2,1",
          "claim": "Travel-service calls to seat take ~1241ms client-side vs ~12ms server-side in abnormal; normal ~14ms client."
        },
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'ab' per, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT c.per, c.service_name caller, p.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_p50_ms, approx_quantile(p.duration,0.5)/1e6 server_p50_ms FROM t c JOIN t p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id AND c.per=p.per WHERE c.attr_span_kind='Client' AND p.attr_span_kind='Server' AND p.service_name='ts-seat-service' GROUP BY ALL ORDER BY 2,1",
          "claim": "Only the travel-service-to-seat edge is slow; travel2, travel-plan and preserve calls to seat stay normal."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'ab' per, attr_source, attr_destination, count(*) n, avg(value) v FROM abnormal_metrics_sum WHERE metric='hubble_tcp_flags_total' AND attr_source LIKE '%ts-seat-service%' AND attr_destination LIKE '%ts-travel-service%' GROUP BY 1,2,3",
          "claim": "Seat-to-travel connection flow counters rise in abnormal period, with no hubble drops on that pair."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'ab' per, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT c.per, c.service_name caller, p.service_name callee, p.span_name, count(*) n, approx_quantile(p.duration,0.95)/1e6 server_p95_ms FROM t c JOIN t p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id AND c.per=p.per WHERE c.service_name='ts-travel-service' AND c.attr_span_kind='Client' AND p.service_name='ts-seat-service' GROUP BY ALL ORDER BY 1",
          "claim": "Travel-service spans waiting on seat calls grow from tens of ms to over 1.2 seconds in abnormal period."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'ab' per, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT c.per, c.service_name caller, p.service_name callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 client_p95_ms, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) client_errs FROM t c JOIN t p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id AND c.per=p.per WHERE c.service_name='ts-route-plan-service' AND p.service_name='ts-travel-service' AND c.attr_span_kind='Client' GROUP BY ALL ORDER BY 1",
          "claim": "Route-plan calls into travel-service rise from ~188ms to ~7.5s p95 with connection-reset errors in abnormal."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'ab' per, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT c.per, c.service_name caller, p.service_name callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 client_p95_ms FROM t c JOIN t p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id AND c.per=p.per WHERE c.service_name='ts-travel-plan-service' AND p.service_name='ts-route-plan-service' AND c.attr_span_kind='Client' GROUP BY ALL ORDER BY 1",
          "claim": "Travel-plan calls to route-plan rise to ~8.1s p95 in abnormal from ~1.25s normal."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'ab' per, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT c.per, c.service_name caller, p.service_name callee, p.span_name, count(*) n, approx_quantile(p.duration,0.95)/1e6 server_p95_ms, sum(CASE WHEN p.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM t c JOIN t p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id AND c.per=p.per WHERE c.service_name='ts-ui-dashboard' AND p.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' GROUP BY ALL ORDER BY 1",
          "claim": "Travel-plan server spans seen by ui-dashboard reach ~8-9s p95 in abnormal, with errors appearing."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'ab' per, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT c.per, c.service_name caller, p.service_name callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_p50_ms FROM t c JOIN t p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id AND c.per=p.per WHERE c.service_name='ts-preserve-service' AND p.service_name='ts-travel-service' AND c.attr_span_kind='Client' GROUP BY ALL ORDER BY 1",
          "claim": "Preserve-service calls to travel-service rise from ~68ms p50 to ~2.5s in abnormal period."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'ab' per, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT c.per, c.service_name caller, p.service_name callee, count(*) n, approx_quantile(p.duration,0.95)/1e6 server_p95_ms, sum(CASE WHEN p.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM t c JOIN t p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id AND c.per=p.per WHERE c.service_name='ts-ui-dashboard' AND p.service_name='ts-preserve-service' AND c.attr_span_kind='Client' GROUP BY ALL ORDER BY 1",
          "claim": "Preserve-service spans seen from ui-dashboard rise to ~2.7s p95 with a few errors in abnormal."
        }
      ]
    }
  ]
}
```

